{
  "title": "Discussion on tax filing, domain purchase, and app monetization ideas",
  "topics": [
    {
      "id": "tax-filing-workaround",
      "title": "Tax filing and inspector anecdote",
      "claims": [
        {
          "text": "The author paid 500 UAH to aunt Sveta to handle tax declarations and avoid large fines.",
          "evidence": [1]
        },
        {
          "text": "The inspector had not reviewed the author's declarations for 1.5 years and was later reprimanded.",
          "evidence": [1]
        },
        {
          "text": "Using Sveta's help, the author repaid about 1000 UAH instead of paying all penalties.",
          "evidence": [1]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase and related costs",
      "claims": [
        {
          "text": "User P2 mentions not having bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "User P4 doubts anyone will buy the domain.",
          "evidence": [9]
        },
        {
          "text": "User P4 explains the reluctance is due to the domain being a low‑value item unlikely to generate revenue.",
          "evidence": [10]
        }
      ]
    },
    {
      "id": "app-business-viability",
      "title": "Viability of a web/app product",
      "claims": [
        {
          "text": "Web platforms are considered the easiest but less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "SEO for the web product is poor; the site does not appear even on the 10th Google page.",
          "evidence": [11]
        },
        {
          "text": "No external traffic sources (Instagram, X, Threads) or contextual ads are available.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero due to an immediate paywall.",
          "evidence": [11]
        },
        {
          "text": "Successful similar projects use fast delivery (< 1 week) and cross‑platform stacks like Flutter.",
          "evidence": [12]
        }
      ]
    },
    {
      "id": "source-code-password",
      "title": "Source code access and password concerns",
      "claims": [
        {
          "text": "User P1 asks whether the source code can be found by searching for a password.",
          "evidence": [21]
        },
        {
          "text": "User P4 sarcastically replies they did not pay 299 UAH for it.",
          "evidence": [22]
        },
        {
          "text": "User P4 later describes the project as a “free vibe‑code” where the password is publicly accessible.",
          "evidence": [30, 32]
        }
      ]
    },
    {
      "id": "scam-perception",
      "title": "Perception of the project as a scam",
      "claims": [
        {
          "text": "User P4 calls the project a scam.",
          "evidence": [32]
        },
        {
          "text": "User P5 affirms that assessment.",
          "evidence": [33]
        }
      ]
    }
  ],
